 22	function tableCells(line) {
 23	  // A pipe inside a backticked Markdown code span is part of the criterion.
 24	  const cells = [''];
 25	  for (const [part] of line.slice(1, -1).matchAll(/`[^`]*`|\\\||[^|`\\]+|./g)) {
 26	    if (part === '|') cells.push('');
 27	    else cells[cells.length - 1] += part;
 28	  }
 29	  return cells.map(cell => cell.trim());
 30	}
