 32	function specIds(spec) {
 33	  const entries = new Map();
 34	  const diagnosticCodes = new Set();
 35	  const typeRows = new Map([
 36	    ['Picking by pointer', 'pointer'], ['Tooltip content', 'tooltip'],
 37	    ['Keyboard order', 'keyboard'], ['Zoom', 'zoom'], ['Simplified drawing when dense', 'dense'],
 38	    ['Limit that raises a diagnostic', 'limit'], ['Reference lines and bands', 'reference'],
 39	  ]);
 40	  const add = (id, type = null) => {
 41	    if (entries.has(id)) throw new Error(`duplicate criterion in spec: ${id}`);
 42	    entries.set(id, type);
 43	  };
 44	  let section;
 45	  let columns;
 46	  for (const raw of spec.split(/\r?\n/)) {
 47	    const line = raw.trim();
 48	    const heading = /^#{2,6}\s+(\d+(?:\.\d+)?)\.?(?:\s|$)/.exec(line);
 49	    if (heading) {
 50	      section = heading[1];
 51	      columns = undefined;
 52	    }
 53	    if (!line.startsWith('|') || !line.endsWith('|')) continue;
 54	    const [label, ...values] = tableCells(line);
 55	    const id = label.replace(/[*_`]/g, '').trim();
 56	    if (/^[A-Z]+\d+$/.test(id)) {
 57	      if (['3.1', '3.2', '3.3', '3.4', '3.7', '4', '5'].includes(section)) add(id);
 58	      else if (/^AX\d+$/.test(id) && section === '3.5') diagnosticCodes.add(id);
 59	      else if (/^(?:3(?:\.|$)|4(?:\.|$)|5(?:\.|$))/.test(section)) {
 60	        throw new Error(`criterion ${id} is in unlisted spec section ${section}`);
 61	      }
 62	    }
 63	    if (section !== '3.6') continue;
 64	    if (!label) {
 65	      columns = values.map(value => value.toLowerCase());
 66	      if (columns.some(type => !chartTypes.includes(type)) || new Set(columns).size !== columns.length) {
 67	        throw new Error('invalid chart types in spec section 3.6');
 68	      }
 69	    } else if (!/^:?-+:?$/.test(label)) {
 70	      const key = typeRows.get(label) ?? label.toLowerCase().replace(/[^a-z\d]+/g, '-').replace(/^-|-$/g, '');
 71	      if (!columns || values.length !== columns.length || values.some(value => !value)) {
 72	        throw new Error(`invalid type matrix row in spec: ${label}`);
 73	      }
 74	      columns.forEach(type => add(`T-${key}-${type}`, type));
 75	    }
 76	  }
 77	  if (!entries.size) throw new Error('no acceptance criteria found in the spec');
 78	  return { entries, diagnosticCodes };
 79	}
