     1	// Adapter references, workloads and noise bands for the runner and the analyzer.
     2	import fs from 'node:fs';
     3	import path from 'node:path';
     4	import { MIN_BAND_PAIRS, MIN_BAND_SESSIONS } from '../src/stats.js';
     5	import { sessionEligibility } from '../src/decision.js';
     6	
     7	export const WORKLOADS = ['first', 'page', 'compact', 'scatter', 'stream', 'theme', 'resize', 'hover', 'zoom', 'mem', 'lifecycle'];
     8	
     9	/**
    10	 * "axylo:renderer=svg,build=dev" -> { id: 'axylo', params: { renderer: 'svg', build: 'dev' } }.
    11	 * Values stay strings except true/false and plain numbers.
    12	 */
    13	export function parseAdapterRef(ref) {
    14	  const [id, rest] = String(ref).split(/:(.*)/s);
    15	  if (!/^[a-z0-9-]+$/.test(id)) throw new Error(`adapter reference "${ref}": the id must be lowercase letters, digits and dashes`);
    16	  const params = {};
    17	  if (rest) for (const part of rest.split(',')) {
    18	    const m = /^([A-Za-z][\w-]*)=(.*)$/.exec(part);
    19	    if (!m) throw new Error(`adapter reference "${ref}": parameter "${part}" is not key=value`);
    20	    params[m[1]] = m[2] === 'true' ? true : m[2] === 'false' ? false : /^-?\d+(\.\d+)?$/.test(m[2]) ? Number(m[2]) : m[2];
    21	  }
    22	  return { id, params };
    23	}
    24	
    25	/** JSON with sorted keys, so two parameter objects compare equal whatever order they were written in. */
    26	export function stableJson(v) {
    27	  if (Array.isArray(v)) return `[${v.map(stableJson).join(',')}]`;
    28	  if (v && typeof v === 'object') return `{${Object.keys(v).filter(k => v[k] !== undefined).sort().map(k => `${JSON.stringify(k)}:${stableJson(v[k])}`).join(',')}}`;
    29	  return JSON.stringify(v);
    30	}
    31	
    32	/**
    33	 * What a noise band must match to be used for a comparison: the measured thing (workload, parameters, settle, pixel
    34	 * ratio), the bytes (every file the A-versus-A run loaded, by hash, must be byte-identical in the comparison's
    35	 * artifact), the browser (Chrome version, headless or headed) and the machine (host name, CPU model, cores).
    36	 * Taken from a history record, so the analyzer derives it from the record it replays.
    37	 */
    38	export function controlsOf(record) {
    39	  const d = record.design ?? {}, env = record.environment ?? {};
    40	  return {
    41	    workload: d.workload, params: d.params, settleMs: d.settleMs, dpr: d.dpr ?? 1,
    42	    chrome: env.browser?.version, headless: env.browser?.headless,
    43	    host: env.host ?? null,
    44	    files: record.hashes?.files ?? null,
    45	    slots: record.hashes?.slots ?? null,
    46	    adapters: [record.design?.baseline, record.design?.candidate].filter(Boolean),
    47	  };
    48	}
    49	
    50	const hostKey = h => (h ? `${h.hostname} / ${h.cpuModel} / ${h.logicalCores} cores` : 'not recorded');
    51	
    52	/** Every reason the A-versus-A record `n` cannot serve as a band for a comparison with controls `c`. */
    53	export function bandMismatches(n, c) {
    54	  const out = [];
    55	  const nc = controlsOf(n);
    56	  // The control must be one of the compared configurations: a uPlot A-versus-A says nothing about Canvas against SVG.
    57	  if (c.adapters?.length && !c.adapters.includes(n.design?.baseline)) out.push(`adapter ${n.design?.baseline}, comparison ${c.adapters.join(' vs ')}`);
    58	  const el = sessionEligibility(n);
    59	  if (!el.eligible) out.push(`session not eligible: ${el.reasons.slice(0, 2).join('; ')}`);
    60	  if (nc.workload !== c.workload) out.push(`workload ${nc.workload}, comparison ${c.workload}`);
    61	  if (stableJson(nc.params) !== stableJson(c.params)) out.push(`parameters ${stableJson(nc.params)}, comparison ${stableJson(c.params)}`);
    62	  if (nc.settleMs !== c.settleMs) out.push(`settle ${nc.settleMs} ms, comparison ${c.settleMs} ms`);
    63	  if (nc.dpr !== c.dpr) out.push(`device pixel ratio ${nc.dpr}, comparison ${c.dpr}`);
    64	  if (nc.chrome !== c.chrome) out.push(`Chrome ${nc.chrome}, comparison ${c.chrome}`);
    65	  if (nc.headless !== c.headless) out.push(`${nc.headless ? 'headless' : 'headed'}, comparison ${c.headless ? 'headless' : 'headed'}`);
    66	  if (!nc.host || !c.host || hostKey(nc.host) !== hostKey(c.host)) out.push(`host ${hostKey(nc.host)}, comparison ${hostKey(c.host)}`);
    67	  // Bytes: every file the band's run loaded must be the same file in one of the comparison's slots.
    68	  const served = n.hashes?.slots?.A?.served;
    69	  if (!served || !Object.keys(served).length) out.push('the band record does not say which files it served (older record)');
    70	  else if (!c.slots) out.push('the comparison does not record its artifact files');
    71	  else {
    72	    const fits = ['A', 'B'].some(slot => {
    73	      const files = c.slots[slot]?.files;
    74	      return files && Object.entries(served).every(([p, h]) => files[p] === h);
    75	    });
    76	    if (!fits) {
    77	      const diff = Object.entries(served).filter(([p, h]) => c.slots.A?.files?.[p] !== h && c.slots.B?.files?.[p] !== h).map(([p]) => p);
    78	      out.push(`built from different bytes: ${diff.slice(0, 4).join(', ')}${diff.length > 4 ? ', …' : ''} differ from both of the comparison's artifacts`);
    79	    }
    80	  }
    81	  return out;
    82	}
    83	
    84	/**
    85	 * Loads one or more complete A-versus-A records and checks each against the comparison's controls. A record that
    86	 * does not match is refused (an error, not a warning): a band from another pixel ratio, build or machine is not
    87	 * this comparison's noise. With several, the band is their union per metric (lowest lo, highest hi). A metric's
    88	 * band is used only from records with at least MIN_BAND_PAIRS complete pairs for it; fewer than
    89	 * MIN_BAND_SESSIONS records (sessions) make the band exploratory, which the report says.
    90	 */
    91	export function loadNoise(refs, historyDir, controls) {
    92	  if (!controls || !controls.workload) throw new Error('loadNoise needs the comparison\'s controls (controlsOf(record))');
    93	  const sources = [], metrics = {}, problems = [];
    94	  for (const ref of refs) {
    95	    const p = fs.existsSync(ref) ? ref : path.join(historyDir, `${ref}.json`);
    96	    if (!fs.existsSync(p)) { problems.push(`noise run ${ref} not found`); continue; }
    97	    const n = JSON.parse(fs.readFileSync(p, 'utf8'));
    98	    if (n.design?.mode !== 'aa' || n.status !== 'complete' || !n.analysis?.metrics) { problems.push(`noise run ${ref} is not a complete, analysed A-versus-A run`); continue; }
    99	    const mism = bandMismatches(n, controls);
   100	    if (mism.length) { problems.push(`noise run ${ref} does not match this comparison: ${mism.join('; ')}`); continue; }
   101	    sources.push({ runId: n.runId, adapter: n.design.baseline, chrome: n.environment.browser.version, dpr: n.design.dpr, completePairs: n.analysis.completePairs });
   102	    for (const [k, m] of Object.entries(n.analysis.metrics)) {
   103	      if (!Number.isFinite(m.lo) || !Number.isFinite(m.hi) || !(m.pairs >= MIN_BAND_PAIRS)) continue;
   104	      const cur = metrics[k];
   105	      metrics[k] = cur ? { lo: Math.min(cur.lo, m.lo), hi: Math.max(cur.hi, m.hi), from: [...cur.from, n.runId] } : { lo: m.lo, hi: m.hi, from: [n.runId] };
   106	    }
   107	  }
   108	  if (problems.length) throw new Error(problems.join('\n'));
   109	  // Counted per metric: a session gives a band for a metric only with enough pairs for that metric, and a band
   110	  // gates only with three such sessions; otherwise it is shown as exploratory and not used to classify.
   111	  for (const m of Object.values(metrics)) {
   112	    m.sessions = new Set(m.from).size;
   113	    m.calibrated = m.sessions >= MIN_BAND_SESSIONS;
   114	    m.calibration = m.calibrated ? `band from ${m.sessions} sessions` : `exploratory: band from ${m.sessions} session${m.sessions === 1 ? '' : 's'} with ${MIN_BAND_PAIRS}+ pairs; plan 3.3 asks for at least ${MIN_BAND_SESSIONS}; not used to classify`;
   115	  }
   116	  const sessions = new Set(sources.map(s => s.runId)).size;
   117	  const calibratedMetrics = Object.entries(metrics).filter(([, m]) => m.calibrated).map(([k]) => k);
   118	  return {
   119	    sources, metrics, sessions,
   120	    calibration: calibratedMetrics.length ? `calibrated for ${calibratedMetrics.join(', ')}; other metrics exploratory` : `exploratory: no metric has ${MIN_BAND_SESSIONS} sessions with ${MIN_BAND_PAIRS}+ pairs (${sessions} session${sessions === 1 ? '' : 's'} given; plan 3.3 asks for at least ${MIN_BAND_SESSIONS} per metric); not used to classify`,
